475	func (s *Service) revokeOrg(ctx context.Context, tx store.Tx, org uuid.UUID, n *int) error {
476		first, _, err := tx.ListBindings(ctx, store.BindingFilter{OrgID: &org}, store.Page{})
477		if err != nil {
478			return err
479		}
480		if err := lockUsers(ctx, tx, principalsOf(first)); err != nil {
481			return err
482		}
483		bs, _, err := tx.ListBindings(ctx, store.BindingFilter{OrgID: &org}, store.Page{})
484		if err != nil {
485			return err
486		}
487		// A grant may have committed while we waited for the first lock set.
488		// Never expand a held sorted lock set: a newly joined, lower-ID user
489		// could invert TransferOwnership's lock order. Roll back; the caller
490		// (including the outbox dispatcher) can retry with a fresh complete set.
491		locked := append([]store.Principal{}, principalsOf(first)...)
492		for _, b := range bs {
493			if b.Principal.Type == rbac.PrincipalUser && !slices.Contains(locked, b.Principal) {
494				return conflict("organization membership changed; retry revocation")
495			}
496		}
497		saIDs, err := tx.ServiceAccountIDsByOrg(ctx, org)
498		if err != nil {
499			return err
500		}
501		skip := make([]store.Principal, 0, len(saIDs))
502		for _, id := range saIDs {
503			skip = append(skip, store.Principal{Type: rbac.PrincipalServiceAccount, ID: id})
504		}
505		deleted, err := deleteOrgAndBump(ctx, tx, bs, skip...)
506		if err != nil {
507			return err
508		}
509		*n = len(deleted)
510		for _, id := range saIDs {
511			sa, err := tx.ServiceAccountByID(ctx, id)
512			if errors.Is(err, store.ErrNotFound) {
513				continue
514			}
515			if err != nil {
516				return err
517			}
518			if _, err := deleteServiceAccountWithLocks(ctx, tx, sa, locked); err != nil && !errors.Is(err, store.ErrNotFound) {
519				return err
520			}
521		}
522		return nil
523	}
